def rane72_owner_profiles():
    """Keep seven unconditional input roles separate from modal pad assignments."""
    ref=RANE72_OWNER_REFERENCES['Rane SEVENTY-TWO'];p=profile('Rane SEVENTY-TWO',ref['url'])
    p.update(definition='reviewed:rane72-djush-unconditional-core',autoSelect=False,
        aliases=['Rane SEVENTY-TWO','Rane Seventy Two','Rane72','Seventy-Two'],
        excludedAliases=['MKII','MK2','Seventy A-Trak','Performer','SYSTEM ONE','TWELVE'],
        hardwareMode='Manual original SEVENTY-TWO exposed MIDI endpoint. Source channel5/6 parameter buttons provide native A/B Play and Sync. Channel16 Browse and A/B Load use the owner mapping. Configure audio separately. Pads, Cue, analogue mixer ownership, screens and MKII remain unqualified.',
        scope='Manual seven-input original Seventy-Two subset: A/B parameter Play/Sync, Browse push A/B Load and signed library Browse. No Cue, pads, mixer, feedback, display, hardware setup or audio-route claim.',gaps=[ref['review']])
    for ch,deck in [(4,'a'),(5,'b')]:
        add(p,'play',ch,40,deck=deck);add(p,'sync',ch,41,deck=deck)
    for deck,n in [('a',2),('b',3)]:add(p,'load',15,n,deck=deck)
    add(p,'browse',15,0,'control','twosComplement')
    return [p]
